  x:["함수 원형. 매개 변수 이름은 생략할 수 있다. (강의 원본은 원형이 int, 정의가 void로 달라 void로 맞춤)","i의 값 10이 복사되어 counter에 전달된다.","매개 변수도 일종의 지역 변수라 함수가 끝나면 사라지고, main의 i에는 영향이 없다."],
