  x:["sub()가 main보다 아래에 정의되어 있어 함수 원형이 필요하다.","main의 반복문 안에서 sub()를 호출한다.","sub()가 끝나면 전역 x는 10이 되고, main의 x++로 11이 되어 main의 반복도 끝난다."],
